import numpy as np
from rdkit import Chem
x=np.load('coordinates.npy');m=Chem.MolFromMolFile('optimized_ligand.mol',removeHs=False)
for i in [62,63,64]:
 print('Distances to',i)
 ds=np.linalg.norm(x[:62]-x[i],axis=1)
 for j in np.argsort(ds)[:9]: print(j,m.GetAtomWithIdx(int(j)).GetSymbol(),round(ds[j],3))
print('B bonds',[(a.GetIdx(),np.linalg.norm(x[a.GetIdx()]-x[0])) for a in m.GetAtomWithIdx(0).GetNeighbors()])
# render structure with bonds
import matplotlib;matplotlib.use('Agg')
import matplotlib.pyplot as plt
fig=plt.figure(figsize=(9,9));ax=fig.add_subplot(projection='3d')
colors={'C':'#404040','H':'#dddddd','N':'#3054ff','O':'#ff3030','B':'#ce9c4a','Co':'#cc3ca8'}
es=[a.GetSymbol() for a in m.GetAtoms()]+['Co','C','O']
for b in m.GetBonds():
 i,j=b.GetBeginAtomIdx(),b.GetEndAtomIdx();ax.plot(*x[[i,j]].T,c='gray',lw=1.5)
for i,j in [(62,2),(62,11),(62,20),(62,63),(63,64)]:ax.plot(*x[[i,j]].T,c='gray',lw=2)
for i,e in enumerate(es):
 ax.scatter(*x[i],s=35 if e=='H' else 100,c=colors[e],depthshade=True)
 if e not in ['C','H']:ax.text(*x[i],e,size=12)
ax.set_box_aspect([1,1,1]);ax.view_init(elev=12,azim=55);ax.set_axis_off();plt.savefig('render.png',dpi=140)
